 public static class Pos {final int x,y,z;public Pos(int a,int b,int c){x=a;y=b;z=c;}public int getX(){return x;}public int getY(){return y;}public int getZ(){return z;}public boolean equals(Object o){return o instanceof Pos p&&p.x==x&&p.y==y&&p.z==z;}public int hashCode(){return x*31+z;}}
 public static class Hit {public Vec3 point;public String type;public Pos pos;public Object entity;public Hit(Vec3 v,String t){point=v;type=t;pos=new Pos((int)Math.floor(v.x),(int)Math.floor(v.y),(int)Math.floor(v.z));}public Vec3 getLocation(){return point;}public String getType(){return type;}public Pos getBlockPos(){return pos;}public Object getEntity(){return entity;}}
