 public static class Entity {public Vec3 position=new Vec3(0,0,2);public net.minecraft.world.phys.AABB getBoundingBox(){return new net.minecraft.world.phys.AABB(-.5,0,1.5,.5,.25,3);}}
 public static class Player {public final Input input=new Input();public boolean gun=true,ads;public int aimCalls;public void aim(boolean aim){ads=aim;aimCalls++;}public float yaw,pitch,yBodyRot;public Vec3 getEyePosition(){return new Vec3(0,1.6,0);}public Object getMainHandItem(){return gun;}public float getXRot(){return pitch;}public float getYRot(){return yaw;}public float getYHeadRot(){return yaw;}public void setXRot(float p){pitch=p;}public void setYRot(float y){yaw=y;}public void setYHeadRot(float y){}public double blockInteractionRange(){return 4.5;}public boolean canInteractWithEntity(Entity e,double extra){return getEyePosition().distanceTo(e.position)<=3;}public void swing(Object hand){}}
